SELECT BUSI_TYPE, TRADE_TYPE, STATUS, COUNT(*) CNT FROM TE_CREDIT_TRADE_BATCH GROUP BY BUSI_TYPE, TRADE_TYPE, STATUS ORDER BY BUSI_TYPE, TRADE_TYPE, STATUS;
SELECT ID, BUSI_TYPE, TRADE_TYPE, STATUS, PRE_STATUS, VALID_FLAG, MEMBER_NAME, CREATE_TIME FROM (SELECT * FROM TE_CREDIT_TRADE_BATCH ORDER BY CREATE_TIME DESC) WHERE ROWNUM <= 8;
SELECT STATUS, COUNT(*) CNT FROM TE_ONLINE_DISC_BATCH GROUP BY STATUS;
SELECT STATUS, COUNT(*) CNT FROM TE_ONLINE_DISC_BILL GROUP BY STATUS;
SELECT ID, BATCH_ID, BILL_NO, STATUS, DISC_IN_BANK_NAME, BILL_MONEY, INTEREST FROM (SELECT * FROM TE_ONLINE_DISC_BILL ORDER BY CREATE_TIME DESC) WHERE ROWNUM <= 10;
